def update_slide(match):
    opening, body = match.group(1), match.group(2)
    title_match = re.search(r'data-title="([^"]+)"', opening)
    if not title_match:
        return match.group(0)
    title = title_match.group(1)
    if title not in mapping:
        return match.group(0)
    value = mapping[title]
    if 'data-explain=' in opening:
        opening = re.sub(r'data-explain="[^"]*"', f'data-explain="{value}"', opening)
    else:
        opening = opening[:-1] + f' data-explain="{value}">'
    if '<footer class="s-foot"></footer>' not in body:
        aside_at = body.find('  <aside class="notes">')
        if aside_at >= 0:
            body = body[:aside_at] + '  <footer class="s-foot"></footer>\n' + body[aside_at:]
    return opening + body

text, changed = re.subn(r'(<section class="slide\b[^>]*>)(.*?)(?=</section>)', update_slide, text, flags=re.S)
assert changed >= 30
assert all(f'data-title="{title}"' in text and f'data-explain="{value}"' in text for title, value in mapping.items())

